  render: function OpensDialogExample() {
    const [open, setOpen] = useState(false);
    const trigger = useRef<HTMLButtonElement>(null);
    return <div className="p-6">
        <Menu>
          <MenuTarget asChild ref={trigger}>
            <Button>작업</Button>
          </MenuTarget>
          <MenuDropdown onCloseAutoFocus={event => {
          if (open) event.preventDefault();
        }}>
            <MenuItem onSelect={() => setOpen(true)}>수정</MenuItem>
          </MenuDropdown>
        </Menu>
        <Dialog open={open} onOpenChange={setOpen}>
          <DialogContent title="문서 수정" onCloseAutoFocus={event => {
          event.preventDefault();
          trigger.current?.focus();
        }}>
            <DialogBody>
              <label className="flex flex-col gap-2">
                문서 이름
                <input defaultValue="작업 문서" className="border p-2" />
              </label>
              <DialogClose asChild>
                <Button className="mt-4">완료</Button>
              </DialogClose>
            </DialogBody>
          </DialogContent>
        </Dialog>
      </div>;
  }
